cat > /tmp/cdp.mjs <<'EOF'
const pages=await (await fetch('http://localhost:9222/json')).json();
const page=pages.find(p=>p.type==='page' && p.url.includes('3002'));
const ws=new WebSocket(page.webSocketDebuggerUrl);
const pending=new Map();let id=0;
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}else if(m.method==='Runtime.exceptionThrown')console.log('EXC',JSON.stringify(m.params.exceptionDetails,null,2));else if(m.method==='Runtime.consoleAPICalled')console.log('CONSOLE',m.params.type,m.params.args.map(a=>a.value||a.description).join(' '));};
await new Promise(r=>ws.onopen=r);
const send=(method,params={})=>new Promise(r=>{let i=++id;pending.set(i,r);ws.send(JSON.stringify({id:i,method,params}));});
await send('Runtime.enable');
await send('Log.enable');
const r=await send('Runtime.evaluate',{expression:`JSON.stringify({matched:document.querySelector('canvas').width, ctx:!!document.querySelector('canvas').getContext('2d'), content:document.body.innerText.slice(0,100)})`,returnByValue:true});
console.log(r.result.result.value);
await new Promise(r=>setTimeout(r,500));
